# Prints each binary that resolves on this host, with its source path.
$bins = @(
  'python','python3','py','perl','ruby','php',
  'powershell','pwsh','cscript','wscript','mshta',
  'node','java',
  'nc','ncat','netcat','socat',
  'curl','wget','certutil','bitsadmin','openssl','ssh'
)
foreach ($b in $bins) {
  $c = Get-Command $b -ErrorAction SilentlyContinue
  if ($c) { '{0,-12} {1}' -f $b, $c.Source }
}
